-- Migration 423: AA-1048 (S281 lane l8) — the per-step bars of the two-step claim-instrument evaluation and the size of
-- a fresh-pool labelling sheet, in the platform settings registry (CIS 407; tech lead S279: a threshold, limit or cap
-- is a setting on Platform › Settings, never a code literal or an env var alone).
--
-- Why. Three one-prompt rounds of the claim instrument were no_go and the last two traded one side for the other, so
-- the next design is a two-step instrument (step 1: restatement of the source or new claim; step 2: is each new
-- specific supported), measured on a fresh pool of R1-fired claims from pieces no earlier round touched
-- (services/ground_truth/two_step.py and fresh_pool.py, stage adhoc_aa1048). Its pre-registration fixes the overall
-- bars (the two instrument_eval bars of CIS 417, unchanged) plus one bar per step; the fresh pool's sheet needs a size.
-- They are policy, so they live here. The run's cap and claim limits stay the CIS 417 keys.
--
-- What:
--   1. Four rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py into
--      shared/settings/compiled_defaults.json in this PR), each with its plain label and EN + VI guide (CIS 416):
--        cis.quality.claim_two_step_route_tp_min_pct       pct 0..100, default 95, maker-checker, evidence required
--        cis.quality.claim_two_step_judge_tp_keep_min_pct  pct 0..100, default 95, maker-checker, evidence required
--        cis.quality.claim_two_step_judge_fp_drop_min_pct  pct 0..100, default 40, maker-checker, evidence required
--        cis.quality.claim_fresh_pool_sample_max           int claims 1..1000, default 150, maker-checker
--      The defaults are the values of the pre-registration file
--      (services/ground_truth/preregistration/aa1048_two_step_v5.json); a live run refuses while the settings differ.
--      Seeded with enforced = false: the code that reads them ships in the next PR of this lane (MIG-4), and the
--      settings-lint guard refuses an enforced key that no code reads. A later migration marks them enforced (with the
--      five CIS 417 keys, whose code is deployed) once the two-step code is on Dev.
--   2. Register 423.
--
-- Behaviour on apply. None for running code: no value row is seeded and nothing reads the keys until the two-step code
-- is deployed; then every key resolves to its default until an administrator approves a change.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: a migration-only PR in the wave's CIS migration batch; applied on Dev by Infra Migration Apply when the job
-- tables are idle (ADR 0017a). DM-7.1: no new table.
--
-- Number. Main ends at 420; this wave's other CIS lanes hold 421-429, so the lane takes 423. If the owner main max + 1
-- differs at merge, renumber (git grep '423_' and '423' here, in tests/integration/test_aa1048_migration_423.py,
-- compiled_defaults.json and the seed-parity test).
--
-- Locks. One INSERT of four rows (the definition guard trigger allows the file's role, cis_owner). lock_timeout 5s.
-- Idempotent (ON CONFLICT (key) DO NOTHING), one transaction, self-registering.
--
-- Rollback (a new forward migration, after the two-step code is reverted): DELETE the four keys (no value row can exist
-- before the code reads them; a value row would have to go first).

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$[
{"key": "cis.quality.claim_two_step_route_tp_min_pct", "app": "cis", "area": "quality", "label": "Two-step claim checker test: real problems passed to the second step", "description": "Per-step go / no-go bar of the two-step claim-instrument evaluation: step 1 (restatement of the source or new claim) must send at least this percentage of the subset's stored violations on to step 2. A violation that step 1 calls a restatement is lost for good. Fixed in the pre-registration before any data; read by the two-step evaluation from the release that ships it; marked enforced by a later migration.", "value_type": "pct", "unit": "%", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 95, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": false, "guide": {"en": {"what": "The two-step version of the claim checker (the AI check that flags statements in written content that the source material does not back up) first sorts each flagged statement: does it only repeat the source in other words, or does it add something new? Only statements that add something go on to the second step, which checks them against the source. This is the share of real problems (confirmed violations) the first step must pass on to pass its test run.", "raise": "Almost no real problem is waved through by the first step, but a first step that sorts well yet lets one or two problems slip fails the test.", "lower": "A first step that waves through more real problems can still pass, so more unsupported statements may never reach the second check.", "when": "Raise it when published content turns out to hold a problem the first step called a plain restatement; lower it only with evidence that the problems it misses are minor.", "example": "With the default of 95%, the first step must pass on at least 95 of every 100 real problems in the test set."}, "vi": {"what": "Phiên bản hai bước của bộ kiểm tra câu khẳng định (bước AI đánh dấu những câu trong bài viết mà tài liệu nguồn không chứng minh được) trước hết phân loại từng câu bị đánh dấu: câu chỉ nói lại tài liệu nguồn bằng lời khác, hay thêm điều gì mới? Chỉ những câu thêm điều mới mới được chuyển sang bước hai để đối chiếu với nguồn. Đây là tỷ lệ lỗi thật (vi phạm đã xác nhận) mà bước một phải chuyển tiếp thì mới đạt lần chạy thử.", "raise": "Gần như không lỗi thật nào bị bước một cho qua, nhưng một bước một phân loại tốt mà để lọt một hai lỗi vẫn bị trượt.", "lower": "Bước một để lọt nhiều lỗi thật hơn vẫn có thể đạt, nên nhiều câu không có căn cứ có thể không bao giờ tới được bước kiểm tra thứ hai.", "when": "Tăng khi phát hiện nội dung đã đăng còn lỗi mà bước một coi là chỉ nói lại nguồn; chỉ giảm khi có bằng chứng rằng những lỗi nó bỏ sót là nhỏ.", "example": "Với mặc định 95%, bước một phải chuyển tiếp ít nhất 95 trên mỗi 100 lỗi thật trong bộ thử."}}},
{"key": "cis.quality.claim_two_step_judge_tp_keep_min_pct", "app": "cis", "area": "quality", "label": "Two-step claim checker test: real problems the second step must flag", "description": "Per-step go / no-go bar of the two-step claim-instrument evaluation: of the stored violations step 1 sent on, step 2 (is each new specific supported by the source) must flag at least this percentage. Fixed in the pre-registration before any data; read by the two-step evaluation from the release that ships it; marked enforced by a later migration.", "value_type": "pct", "unit": "%", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 95, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": false, "guide": {"en": {"what": "The second step of the two-step version of the claim checker (the AI check that flags statements in written content that the source material does not back up) checks only the statements the first step found to add something new, and decides whether the source backs up what they add. This is the share of the real problems reaching it (confirmed violations) that the second step must still flag to pass its test run.", "raise": "Almost every real problem that reaches the second step stays caught, but it gets harder for a new second-step prompt to pass.", "lower": "A second step that clears more real problems can pass, so more unsupported statements can reach published content.", "when": "Raise it when published content turns out to hold a problem the second step judged as supported; lower it only with evidence that the missed cases are minor.", "example": "With the default of 95%, the second step must flag at least 95 of every 100 real problems it is given in the test set."}, "vi": {"what": "Bước hai của phiên bản hai bước của bộ kiểm tra câu khẳng định (bước AI đánh dấu những câu trong bài viết mà tài liệu nguồn không chứng minh được) chỉ kiểm những câu mà bước một thấy có thêm điều mới, và quyết định tài liệu nguồn có chứng minh được điều thêm vào hay không. Đây là tỷ lệ lỗi thật (vi phạm đã xác nhận) tới được bước hai mà bước hai vẫn phải đánh dấu thì mới đạt lần chạy thử.", "raise": "Gần như mọi lỗi thật tới được bước hai vẫn bị bắt, nhưng prompt mới cho bước hai sẽ khó đạt hơn.", "lower": "Bước hai bỏ qua nhiều lỗi thật hơn vẫn có thể đạt, nên nhiều câu không có căn cứ có thể lọt vào nội dung đã đăng.", "when": "Tăng khi phát hiện nội dung đã đăng còn lỗi mà bước hai coi là có căn cứ; chỉ giảm khi có bằng chứng rằng những trường hợp bị bỏ sót là nhỏ.", "example": "Với mặc định 95%, bước hai phải đánh dấu ít nhất 95 trên mỗi 100 lỗi thật được chuyển tới nó trong bộ thử."}}},
{"key": "cis.quality.claim_two_step_judge_fp_drop_min_pct", "app": "cis", "area": "quality", "label": "Two-step claim checker test: false alarms the second step must clear", "description": "Per-step go / no-go bar of the two-step claim-instrument evaluation: of the false positives (claims judged ok that the R1 instrument fired on) step 1 sent on, step 2 must clear at least this percentage. When step 1 cleared every false positive the bar holds. Fixed in the pre-registration before any data; read by the two-step evaluation from the release that ships it; marked enforced by a later migration.", "value_type": "pct", "unit": "%", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 40, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": false, "guide": {"en": {"what": "Some false alarms (statements the review panel judged fine that the claim checker (the AI check that flags statements in written content that the source material does not back up) flagged) still reach the second step of its two-step version, because the first step thought they add something new. This is the share of those false alarms the second step must clear to pass its test run. The overall bar for false alarms cleared applies on top.", "raise": "Only a second step that clears most of the false alarms reaching it passes, so fewer good texts are held for review, but fewer new prompts will pass at all.", "lower": "A second step passes while clearing fewer false alarms, so reviewers keep seeing more wrong flags, as long as the overall bar still holds.", "when": "Raise it when reviewers report many wrong flags on statements that only add harmless detail; lower it when a second step fails by a small margin while the overall result is clearly better.", "example": "With the default of 40%, the second step must clear at least 40 of every 100 false alarms it is given in the test set."}, "vi": {"what": "Một số báo động nhầm (câu hội đồng duyệt xác nhận là đúng nhưng bộ kiểm tra câu khẳng định (bước AI đánh dấu những câu trong bài viết mà tài liệu nguồn không chứng minh được) vẫn đánh dấu) vẫn tới bước hai của phiên bản hai bước, vì bước một cho rằng chúng có thêm điều mới. Đây là tỷ lệ báo động nhầm như vậy mà bước hai phải loại bỏ thì mới đạt lần chạy thử. Ngưỡng chung về báo động nhầm vẫn áp dụng thêm.", "raise": "Chỉ bước hai loại được phần lớn báo động nhầm tới tay nó mới đạt, nên ít bài tốt bị giữ lại chờ duyệt hơn, nhưng sẽ ít prompt mới đạt hơn.", "lower": "Bước hai loại được ít báo động nhầm hơn vẫn đạt, nên người duyệt vẫn gặp nhiều cảnh báo sai hơn, miễn là ngưỡng chung vẫn giữ được.", "when": "Tăng khi người duyệt báo nhiều cảnh báo sai ở những câu chỉ thêm chi tiết vô hại; giảm khi bước hai trượt trong gang tấc trong khi kết quả chung rõ ràng tốt hơn.", "example": "Với mặc định 40%, bước hai phải loại được ít nhất 40 trên mỗi 100 báo động nhầm được chuyển tới nó trong bộ thử."}}},
{"key": "cis.quality.claim_fresh_pool_sample_max", "app": "cis", "area": "quality", "label": "Claim checker test: statements drawn for a fresh label sheet", "description": "The most claims one fresh-pool sample may draw for the labelling sheet of a claim-instrument evaluation (R1-fired claims on pieces no earlier evaluation touched; the agent panel labels every drawn claim, then about half are false positives and half violations). Read by the fresh-pool builder from the release that ships it; marked enforced by a later migration.", "value_type": "int", "unit": "claims", "min_value": 1, "max_value": 1000, "allowed_values": null, "default_value": 150, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": false, "guide": {"en": {"what": "How many statements are drawn for a fresh label sheet before a test run of the claim checker (the AI check that flags statements in written content that the source material does not back up). They are statements the current checker flagged in content that no earlier test used; a review panel labels each one as a real problem or a false alarm, and the test then draws its statements from them.", "raise": "The test has enough real problems to give a firm result, but the panel has more statements to label before the test can start.", "lower": "Labelling is quicker, but the sheet may hold too few real problems for the test run, so the pass / fail result rests on fewer statements.", "when": "Raise it when the labelled sheet holds fewer real problems than the test run needs; lower it when the sheet regularly holds far more than the run uses.", "example": "With the default of 150, the sheet holds up to 150 flagged statements, which usually gives enough real problems and false alarms for a test run of 50."}, "vi": {"what": "Số câu được rút ra cho một bảng gán nhãn mới trước khi chạy thử bộ kiểm tra câu khẳng định (bước AI đánh dấu những câu trong bài viết mà tài liệu nguồn không chứng minh được). Đó là những câu bộ kiểm tra hiện tại đã đánh dấu trong nội dung chưa lần thử nào dùng tới; hội đồng duyệt gán nhãn từng câu là lỗi thật hay báo động nhầm, rồi lần chạy thử rút câu từ đó.", "raise": "Lần chạy thử có đủ lỗi thật để cho kết quả chắc chắn, nhưng hội đồng phải gán nhãn nhiều câu hơn trước khi chạy thử được.", "lower": "Gán nhãn nhanh hơn, nhưng bảng có thể chứa quá ít lỗi thật cho lần chạy thử, nên kết luận đạt hay không đạt dựa trên ít câu hơn.", "when": "Tăng khi bảng đã gán nhãn có ít lỗi thật hơn mức lần chạy thử cần; giảm khi bảng thường xuyên có nhiều hơn hẳn số câu lần chạy dùng.", "example": "Với mặc định 150, bảng chứa tối đa 150 câu đã bị đánh dấu, thường đủ lỗi thật và báo động nhầm cho một lần chạy thử 50 câu."}}}
]$seed$::jsonb) AS s (key text, app text, area text, label text, description text, value_type text, unit text,
                      min_value numeric, max_value numeric, allowed_values jsonb, default_value jsonb, scope_kind text,
                      impact text, approval text, evidence_required boolean, env_override text, cache_s integer,
                      enforced boolean, guide jsonb)
ON CONFLICT (key) DO NOTHING;
-- settings-seed:end

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('423', now(), 'AA-1048: two-step claim-instrument step bars and the fresh-pool sheet size')
ON CONFLICT (version) DO NOTHING;

COMMIT;
